  const query=new URLSearchParams({name:request.name,license:request.rights.license,attribution:request.rights.attribution,permissionConfirmed:String(request.rights.permissionConfirmed)});if(request.rights.licenseUrl)query.set('licenseUrl',request.rights.licenseUrl);
  const r=await fetch(`${SERVICE}/three-d/packages/import?${query}`,{method:'POST',headers:{'Content-Type':'application/octet-stream','X-GeoD-Client':'geod-global'},body:file,signal:AbortSignal.timeout(190000)});const p=await r.json();if(!r.ok)throw new Error(p.error||'3D import failed');return validateThreeDPackage(p);
