export async function exportThreeD(id){if(!uuid.test(id))throw new Error('Invalid 3D asset identifier');if(desktopAvailable()){try{return await window.__TAURI__.core.invoke('export_three_d',{id});}catch(e){throw new Error(String(e));}}const r=await fetch(`${SERVICE}/three-d/packages/${id}/export`);if(!r.ok)throw new Error((await r.json()).error||'3D export failed');if(r.headers.get('content-type')!=='application/zip')throw new Error('3D export did not return a ZIP');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=`geod-3d-${id}.zip`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return true;}
const decoder=new TextDecoder('utf-8',{fatal:true}),encoder=new TextEncoder();
